INSERT INTO speaking_roulette_topics (part, topic, cue_card, questions, sample_ideas, vocabulary, hint, color_theme)
VALUES
('Part 1', 'Walking & Exercise', NULL, '["How much walking do you usually do in a day?","Do you prefer walking or taking public transport?","Did you walk more when you were younger?","Where do you usually go for a walk?","Would you like to exercise more in the future?"]'::jsonb, '["Daily step count & walking habits","Physical & mental health benefits","Favorite walking routes or parks","Comparison between present and childhood activity levels"]'::jsonb, '[{"sentence":"I try to get at least ten thousand steps daily to stay in good shape.","word":"ten thousand steps","def":"A standard daily walking exercise target","meaning":"Mục tiêu 10.000 bước chân"},{"sentence":"Walking through the botanical garden is a refreshing way to unwind.","word":"unwind","def":"To relax after a period of work or tension","meaning":"Thư giãn, xả stress"},{"sentence":"I find morning brisk walking immensely invigorating.","word":"brisk walking","def":"Fast and energetic walking","meaning":"Đi bộ nhanh"},{"sentence":"Regular physical exercise is a cornerstone of cardiovascular health.","word":"cardiovascular","def":"Relating to the heart and blood vessels","meaning":"Tim mạch"}]'::jsonb, 'Use adverbs of frequency (e.g. ''on a regular basis'', ''sporadically'') and describe physical well-being benefits.', 'sage'),
('Part 1', 'Food & International Food', NULL, '["What kind of food do you usually eat?","Do you often eat food from other countries?","Is there any foreign food that you don''t like?","Have you ever tried cooking an international dish?","What Vietnamese food would you recommend to a foreign visitor?"]'::jsonb, '["Staple everyday dishes vs. special cuisines","Experience with international flavors (Italian, Japanese, etc.)","Traditional home-cooked Vietnamese specialties","Willingness to experiment with unfamiliar ingredients"]'::jsonb, '[{"sentence":"I have a strong penchant for authentic Mediterranean cuisine.","word":"penchant","def":"A strong or habitual liking for something","meaning":"Sở thích, thiên hướng"},{"sentence":"Vietnamese street food is renowned for its balanced and fragrant herbs.","word":"fragrant","def":"Having a pleasant, sweet smell","meaning":"Thơm phức"},{"sentence":"I usually avoid processed snacks in favor of wholesome organic meals.","word":"wholesome","def":"Promoting health and well-being","meaning":"Lành mạnh, bổ dưỡng"},{"sentence":"Sampling exotic dishes expands one''s culinary horizons.","word":"culinary horizons","def":"One''s range of food knowledge and taste","meaning":"Tầm nhìn ẩm thực"}]'::jsonb, 'Describe textures (crispy, tender, savoury) and contrast home-cooked vs dining out.', 'sand'),
('Part 1', 'Fruit', NULL, '["What is your favourite fruit?","How often do you eat fruit?","Is there any fruit you dislike?","Do you prefer fresh fruit or fruit juice?","Is fruit expensive where you live?"]'::jsonb, '["Favorite seasonal fruits (mango, watermelon, dragonfruit)","Health benefits & vitamins","Fresh fruits vs. processed fruit juices","Fruit pricing and availability at local markets"]'::jsonb, '[{"sentence":"Tropical fruits like mangoes and lychees are in abundant supply during summer.","word":"abundant supply","def":"Existing in large quantities","meaning":"Nguồn cung dồi dào"},{"sentence":"Fresh fruit is packed with essential dietary fiber and antioxidants.","word":"antioxidants","def":"Substances that protect cells from damage","meaning":"Chất chống oxy hóa"},{"sentence":"I prefer whole fruits over packaged juices which contain added sugar.","word":"whole fruits","def":"Fruits in their natural unadulterated form","meaning":"Trái cây nguyên quả"}]'::jsonb, 'Mention seasonal variations and nutritional value.', 'rust'),
('Part 1', 'Cafés', NULL, '["Do you often go to cafés?","What do you usually do when you are in a café?","What makes a café attractive to you?","Do you prefer quiet or busy cafés?","Have cafés become more popular among young people?"]'::jsonb, '["Frequency of visiting coffee shops","Atmosphere & interior ambiance (cozy, quiet vs vibrant)","Productivity or social gathering spot","The booming café culture among young people"]'::jsonb, '[{"sentence":"I frequently patronise independent boutique coffee shops.","word":"patronise","def":"To be a regular customer of a store or cafe","meaning":"Lui tới, làm khách quen"},{"sentence":"The rustic interior and ambient lighting create a tranquil study environment.","word":"tranquil","def":"Calm, quiet, and peaceful","meaning":"Yên tĩnh, thanh bình"},{"sentence":"Cafés have evolved into bustling social hubs for the youth.","word":"social hubs","def":"Central places where people gather to socialize","meaning":"Trung tâm giao lưu"}]'::jsonb, 'Discuss ambience, music, workspace ergonomics, and coffee quality.', 'slate'),
('Part 1', 'Holidays', NULL, '["Do you usually spend holidays with your family or friends?","What kind of holiday do you enjoy most?","What type of accommodation do you prefer?","Do you usually plan your holidays carefully?","Where would you like to go on your next holiday?"]'::jsonb, '["Preferred vacation style (beach retreat, mountain trek, cultural city break)","Travel companions (family, solo, close friends)","Planning in advance vs spontaneous trips","Dream destinations for upcoming getaways"]'::jsonb, '[{"sentence":"I prefer venturing off the beaten track to escape tourist crowds.","word":"off the beaten track","def":"In a place where few people go, secluded","meaning":"Nơi hoang sơ, ít người tới"},{"sentence":"A relaxing coastal retreat allows me to recharge my batteries.","word":"recharge my batteries","def":"To rest and regain energy","meaning":"Nạp lại năng lượng"},{"sentence":"I appreciate itineraries that balance sightseeing with leisure time.","word":"itineraries","def":"Planned routes or journeys","meaning":"Lịch trình du lịch"}]'::jsonb, 'Use past tense for memorable experiences and hypothetical conditionals (''If given the chance, I would...'').', 'coral'),
('Part 1', 'Museums', NULL, '["Did you enjoy visiting museums when you were a child?","How often do you visit museums nowadays?","Is there an interesting museum near where you live?","Do you prefer visiting museums alone or with other people?","Would you visit a museum when travelling abroad?"]'::jsonb, '["Childhood memories of museum excursions","Types of exhibits (history, modern art, science)","Educational value vs interactive digital exhibits","Visiting cultural venues while travelling abroad"]'::jsonb, '[{"sentence":"Historical museums showcase invaluable cultural artifacts and relics.","word":"artifacts","def":"Objects of historical or cultural interest","meaning":"Hiện vật lịch sử"},{"sentence":"Interactive multimedia displays make exhibitions much more engaging.","word":"engaging","def":"Charming, attractive, and interesting","meaning":"Lôi cuốn, hấp dẫn"},{"sentence":"Preserving historical heritage is essential for future generations.","word":"heritage","def":"Valued objects and qualities passed down through years","meaning":"Di sản"}]'::jsonb, 'Talk about preservation of cultural identity and hands-on learning experiences.', 'moss'),
('Part 1', 'Personal Qualities', NULL, '["What do you think is your best personal quality?","What quality do you value most in a friend?","Are you similar to your parents in terms of personality?","Is there a personal quality you would like to develop?","Do you think you would make a good leader?"]'::jsonb, '["Key personal strengths (resilience, empathy, punctuality)","Qualities valued most in close friendships","Inherited traits vs developed habits","Leadership aptitude and emotional intelligence"]'::jsonb, '[{"sentence":"I consider adaptability and emotional resilience to be my greatest strengths.","word":"resilience","def":"The capacity to recover quickly from difficulties","meaning":"Sự kiên cường, bền bỉ"},{"sentence":"Trustworthiness and empathy are the bedrock of any lasting relationship.","word":"bedrock","def":"The fundamental principles or foundation","meaning":"Nền tảng vững chắc"},{"sentence":"An effective leader must possess strong interpersonal skills.","word":"interpersonal skills","def":"Skills used to interact with other people","meaning":"Kỹ năng giao tiếp ứng xử"}]'::jsonb, 'Use reflective adjectives and specific personal anecdotes.', 'amber'),
('Part 1', 'Films & TV', NULL, '["How often do you watch films?","What kind of films do you enjoy?","Do you prefer watching films at home or at the cinema?","Is there a film you would like to watch again?","Do you usually watch films alone or with friends?"]'::jsonb, '["Preferred genres (sci-fi, documentaries, historical drama)","Cinema experience vs home streaming platforms","Memorable movies that left a lasting impression","Social aspects of watching films together"]'::jsonb, '[{"sentence":"I am captivated by thought-provoking psychological thrillers.","word":"thought-provoking","def":"Stimulating careful consideration or thought","meaning":"Kích thích tư duy"},{"sentence":"The cinematic visuals and surround sound make movie theatres irreplaceable.","word":"cinematic visuals","def":"High-quality movie visuals and effects","meaning":"Hình ảnh điện ảnh"},{"sentence":"Online streaming services offer an unprecedented variety of on-demand content.","word":"on-demand","def":"Available when required or requested","meaning":"Theo yêu cầu"}]'::jsonb, 'Discuss plot twists, character development, and cinematography.', 'indigo'),
('Part 1', 'Music', NULL, '["What kind of music do you usually listen to?","When do you normally listen to music?","Has your taste in music changed over time?","Do you prefer listening to music alone or with other people?","Is live music popular among young people in your country?"]'::jsonb, '["Musical genres and listening habits","Impact of melodies on mood and productivity","Evolution of music tastes over time","Energy of live concerts and music festivals"]'::jsonb, '[{"sentence":"Uplifting acoustic melodies help alleviate stress during long workdays.","word":"alleviate stress","def":"To make suffering or stress less severe","meaning":"Giảm bớt căng thẳng"},{"sentence":"My musical preferences have diversified significantly over the years.","word":"diversified","def":"Became more varied","meaning":"Đa dạng hóa"},{"sentence":"The electrifying atmosphere of live gigs is truly unforgettable.","word":"electrifying","def":"Causing great excitement or enthusiasm","meaning":"Đầy phấn khích, bùng nổ"}]'::jsonb, 'Use sensory language and explain how music serves as an emotional outlet.', 'sage'),
('Part 1', 'Transport & Travelling by Plane', NULL, '["How often do you travel by public transport?","Do you enjoy travelling by plane?","What is your favourite way of travelling?","Would you like to live near an airport?","Do you think you will travel more in the future?"]'::jsonb, '["Daily public transit commute experience","Pros and cons of air travel","Infrastructure near residential airports","Future transport innovations (high-speed rail, hyperloop)"]'::jsonb, '[{"sentence":"Public transit helps alleviate gridlock traffic congestion in metropolitan areas.","word":"gridlock","def":"A traffic jam affecting a whole network of streets","meaning":"Ùn tắc giao thông"},{"sentence":"Long-haul flights can be physically exhausting despite modern airline amenities.","word":"long-haul","def":"Travelling over long distances","meaning":"Chuyến bay đường dài"},{"sentence":"Investing in sustainable electric bus fleets reduces carbon emissions.","word":"carbon emissions","def":"Carbon dioxide released into the atmosphere","meaning":"Khí thải carbon"}]'::jsonb, 'Contrast convenience vs environmental sustainability and cost.', 'sand'),
('Part 1', 'Weekends', NULL, '["What do you usually do at weekends?","Do you prefer relaxing or being active at weekends?","Did you spend your weekends differently when you were younger?","Do you usually make plans for the weekend?","Would you like to have longer weekends?"]'::jsonb, '["Balancing relaxation with productive hobbies","Active outdoor activities vs restful indoor time","Past weekend routines vs modern adult schedules","Desirability of a 4-day working week"]'::jsonb, '[{"sentence":"I like striking a healthy balance between downtime and social outings.","word":"downtime","def":"Time spent relaxing and doing nothing","meaning":"Thời gian nghỉ ngơi"},{"sentence":"A four-day work week could significantly boost employee productivity and well-being.","word":"boost productivity","def":"Increase the efficiency of work","meaning":"Thúc đẩy năng suất"},{"sentence":"Weekends allow me to detach from pressing workplace deadlines.","word":"detach","def":"To disconnect mentally or physically","meaning":"Tách rời, rũ bỏ"}]'::jsonb, 'Explain how weekends contribute to mental health and work-life balance.', 'rust'),
('Part 1', 'Study & Work', NULL, '["What do you enjoy most about your studies?","What part of your studies do you find difficult?","Do you prefer studying alone or with other people?","What kind of job would you like to have in the future?","Do you think your studies will help you get that job?"]'::jsonb, '["Core academic subject fascinations and challenges","Independent study vs team collaborations","Career aspirations and target industries","Practical applicability of theoretical coursework"]'::jsonb, '[{"sentence":"I find applied problem-solving far more engaging than rote memorization.","word":"rote memorization","def":"Memorization through repetition without deep understanding","meaning":"Học vẹt"},{"sentence":"Acquiring transferable technical proficiencies opens up versatile career paths.","word":"transferable","def":"Able to be applied in different contexts","meaning":"Có thể chuyển giao, linh hoạt"},{"sentence":"Internships bridge the gap between academic theory and industry reality.","word":"bridge the gap","def":"To connect two different things or reduce disparity","meaning":"Thu hẹp khoảng cách"}]'::jsonb, 'Discuss career milestones, skill development, and lifelong learning.', 'slate'),
('Part 1', 'Technology', NULL, '["What piece of technology do you use most?","How often do you use your phone?","Is there any technology you find difficult to use?","Did you use technology differently when you were younger?","Is there a new technology you would like to try?"]'::jsonb, '["Indispensable digital devices and productivity apps","Smartphone screen time and digital wellbeing","Generational differences in tech adoption","Emerging innovations you are eager to explore"]'::jsonb, '[{"sentence":"Smartphones have become an indispensable extension of our daily lives.","word":"indispensable","def":"Absolutely necessary or essential","meaning":"Không thể thiếu"},{"sentence":"I practice digital detoxes periodically to curb excessive screen time.","word":"digital detox","def":"A period during which one refrains from using tech","meaning":"Cai nghiện thiết bị số"},{"sentence":"Artificial intelligence has streamlined everyday computational tasks.","word":"streamlined","def":"Made more efficient and simpler","meaning":"Tối ưu hóa, tinh gọn"}]'::jsonb, 'Balance the convenience of automation against digital fatigue.', 'coral'),
('Part 1', 'News', NULL, '["How often do you read or watch the news?","Where do you usually get your news?","Do you prefer local or international news?","Is there a type of news you are particularly interested in?","Do you discuss the news with your friends?"]'::jsonb, '["News consumption habits (social feeds vs reputable broadsheets)","Local community updates vs global geopolitical events","Critical thinking and discerning authentic news from misinformation","Discussing current affairs with peers"]'::jsonb, '[{"sentence":"I rely on reputable journalistic outlets to stay abreast of current affairs.","word":"stay abreast of","def":"To remain fully informed about something","meaning":"Bắt kịp, nắm bắt thông tin"},{"sentence":"Media literacy is crucial to weed out fabricated sensationalist stories.","word":"media literacy","def":"Ability to analyze and evaluate media critically","meaning":"Tư duy phản biện truyền thông"},{"sentence":"Sensational headlines often distort objective reality for clickbait.","word":"sensational","def":"Presenting information in a shocking or exaggerated way","meaning":"Giật gân"}]'::jsonb, 'Mention fact-checking, objectivity, and echo chambers on social media.', 'moss'),
('Part 1', 'Plans & Future', NULL, '["Do you usually make plans for your free time?","Are you good at following your plans?","How often do your plans change?","Do you prefer making plans alone or with other people?","What is one plan you have for the near future?"]'::jsonb, '["Short-term goals vs 5-year strategic visions","Flexibility and adapting to unexpected disruptions","Methodology for tracking milestones (journals, digital task boards)","Upcoming major life transitions"]'::jsonb, '[{"sentence":"I formulate structured milestones while maintaining flexibility for contingencies.","word":"contingencies","def":"Future events or circumstances possible but not certain","meaning":"Các tình huống dự phòng"},{"sentence":"Setting concrete actionable targets keeps me consistently motivated.","word":"actionable","def":"Giving sufficient information to be acted on","meaning":"Có tính thực thi cao"},{"sentence":"Long-term ambition requires sustained dedication and resilience.","word":"sustained dedication","def":"Continuing effort over a prolonged duration","meaning":"Sự cống hiến bền bỉ"}]'::jsonb, 'Use future tense, conditional clauses, and intentional phrasing (''I intend to...'', ''My prime aspiration is...'').', 'amber'),
('Part 2', 'A Film You Would Like to Watch Again', 'Describe a film you have seen that you would like to watch again.', '["What the film was and when you watched it","Who you would like to watch it with","Why you would like to watch it again"]'::jsonb, '["Key background context and underlying causes","Specific personal observations and concrete real-life examples","Pros and cons or contrasting viewpoints","Future predictions or broader societal implications"]'::jsonb, '[{"sentence":"Discussing a film you would like to watch again provides valuable insights into modern societal dynamics.","word":"societal dynamics","def":"The patterns and forces of change in society","meaning":"Động lực xã hội"},{"sentence":"It is paramount to evaluate both immediate benefits and long-term consequences.","word":"paramount","def":"More important than anything else; supreme","meaning":"Tối quan trọng"},{"sentence":"Opinions on this matter remain highly polarized among different demographics.","word":"polarized","def":"Divided into sharply contrasting groups or sets of opinions","meaning":"Phân cực, chia rẽ ý kiến"},{"sentence":"Taking a nuanced perspective helps avoid oversimplified generalizations.","word":"nuanced","def":"Characterized by subtle shades of meaning or expression","meaning":"Sâu sắc, đa chiều"}]'::jsonb, 'Structure your response with clear discourse markers, elaborate with concrete illustrations, and maintain fluent speech delivery for Part 2.', 'indigo'),
('Part 2', 'A Time You Changed a Plan', 'Describe a time when you changed a plan you had made.', '["What your original plan was","Why you changed it","How you felt about the new plan"]'::jsonb, '["Key background context and underlying causes","Specific personal observations and concrete real-life examples","Pros and cons or contrasting viewpoints","Future predictions or broader societal implications"]'::jsonb, '[{"sentence":"Discussing a time you changed a plan provides valuable insights into modern societal dynamics.","word":"societal dynamics","def":"The patterns and forces of change in society","meaning":"Động lực xã hội"},{"sentence":"It is paramount to evaluate both immediate benefits and long-term consequences.","word":"paramount","def":"More important than anything else; supreme","meaning":"Tối quan trọng"},{"sentence":"Opinions on this matter remain highly polarized among different demographics.","word":"polarized","def":"Divided into sharply contrasting groups or sets of opinions","meaning":"Phân cực, chia rẽ ý kiến"},{"sentence":"Taking a nuanced perspective helps avoid oversimplified generalizations.","word":"nuanced","def":"Characterized by subtle shades of meaning or expression","meaning":"Sâu sắc, đa chiều"}]'::jsonb, 'Structure your response with clear discourse markers, elaborate with concrete illustrations, and maintain fluent speech delivery for Part 2.', 'sage'),
('Part 2', 'A Piece of Work You Were Proud Of', 'Describe a piece of work you did that you felt very satisfied with.', '["What the work was","Who or what helped you","Why you were satisfied with it"]'::jsonb, '["Key background context and underlying causes","Specific personal observations and concrete real-life examples","Pros and cons or contrasting viewpoints","Future predictions or broader societal implications"]'::jsonb, '[{"sentence":"Discussing a piece of work you were proud of provides valuable insights into modern societal dynamics.","word":"societal dynamics","def":"The patterns and forces of change in society","meaning":"Động lực xã hội"},{"sentence":"It is paramount to evaluate both immediate benefits and long-term consequences.","word":"paramount","def":"More important than anything else; supreme","meaning":"Tối quan trọng"},{"sentence":"Opinions on this matter remain highly polarized among different demographics.","word":"polarized","def":"Divided into sharply contrasting groups or sets of opinions","meaning":"Phân cực, chia rẽ ý kiến"},{"sentence":"Taking a nuanced perspective helps avoid oversimplified generalizations.","word":"nuanced","def":"Characterized by subtle shades of meaning or expression","meaning":"Sâu sắc, đa chiều"}]'::jsonb, 'Structure your response with clear discourse markers, elaborate with concrete illustrations, and maintain fluent speech delivery for Part 2.', 'sand'),
('Part 2', 'A News Story You Discussed', 'Describe a news story that you had a long discussion about.', '["What the news was about","Who you discussed it with","Why the discussion lasted a long time"]'::jsonb, '["Key background context and underlying causes","Specific personal observations and concrete real-life examples","Pros and cons or contrasting viewpoints","Future predictions or broader societal implications"]'::jsonb, '[{"sentence":"Discussing a news story you discussed provides valuable insights into modern societal dynamics.","word":"societal dynamics","def":"The patterns and forces of change in society","meaning":"Động lực xã hội"},{"sentence":"It is paramount to evaluate both immediate benefits and long-term consequences.","word":"paramount","def":"More important than anything else; supreme","meaning":"Tối quan trọng"},{"sentence":"Opinions on this matter remain highly polarized among different demographics.","word":"polarized","def":"Divided into sharply contrasting groups or sets of opinions","meaning":"Phân cực, chia rẽ ý kiến"},{"sentence":"Taking a nuanced perspective helps avoid oversimplified generalizations.","word":"nuanced","def":"Characterized by subtle shades of meaning or expression","meaning":"Sâu sắc, đa chiều"}]'::jsonb, 'Structure your response with clear discourse markers, elaborate with concrete illustrations, and maintain fluent speech delivery for Part 2.', 'rust'),
('Part 2', 'A Law You Agree With', 'Describe a law in your country that you think is a good idea.', '["What the law is","Why and when it was introduced","Why you agree with it"]'::jsonb, '["Key background context and underlying causes","Specific personal observations and concrete real-life examples","Pros and cons or contrasting viewpoints","Future predictions or broader societal implications"]'::jsonb, '[{"sentence":"Discussing a law you agree with provides valuable insights into modern societal dynamics.","word":"societal dynamics","def":"The patterns and forces of change in society","meaning":"Động lực xã hội"},{"sentence":"It is paramount to evaluate both immediate benefits and long-term consequences.","word":"paramount","def":"More important than anything else; supreme","meaning":"Tối quan trọng"},{"sentence":"Opinions on this matter remain highly polarized among different demographics.","word":"polarized","def":"Divided into sharply contrasting groups or sets of opinions","meaning":"Phân cực, chia rẽ ý kiến"},{"sentence":"Taking a nuanced perspective helps avoid oversimplified generalizations.","word":"nuanced","def":"Characterized by subtle shades of meaning or expression","meaning":"Sâu sắc, đa chiều"}]'::jsonb, 'Structure your response with clear discourse markers, elaborate with concrete illustrations, and maintain fluent speech delivery for Part 2.', 'slate'),
