
-- 5. BẢNG SPEAKING ROULETTE TOPICS & QUESTIONS
CREATE TABLE IF NOT EXISTS speaking_roulette_topics (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    part VARCHAR(10) NOT NULL,              -- 'Part 1', 'Part 2', 'Part 3'
    topic VARCHAR(150) NOT NULL,
    cue_card TEXT,                          -- For Part 2
    questions JSONB NOT NULL,               -- Array of questions or bullet points
    sample_ideas JSONB,                     -- Array of talking points/ideas
    vocabulary JSONB,                       -- Array of { sentence, word, definition, meaning }
    hint TEXT,
    color_theme VARCHAR(30) DEFAULT 'sage',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

